    parts = []
    s = []
    s.append(sl('<p>Từ đây là <b>thống kê suy diễn</b>: dùng mẫu để suy ra điều chưa biết về tổng thể. Module 7 xây nền: mẫu ngẫu nhiên, đặc trưng mẫu (x̄, s²), ước lượng điểm và <b>phương pháp hợp lý cực đại</b> (MLE) — nội dung của câu 5 trong đề cuối kỳ.</p>' + ul(['Tập nền, mẫu, đặc trưng mẫu (kể cả bảng tần số/lớp)', 'Ước lượng điểm của μ, σ², p; tính không chệch', 'Hàm hợp lý l(θ) và MLE', 'Các MLE chuẩn: mũ, hình học, Poisson, Bernoulli, chuẩn']),
                'MODULE 7 · Bài học 2 · Chương 2, mục 2.1–2.2 · Kreyszig §25.1–25.2', 'Mẫu, ước lượng điểm và hợp lý cực đại',
                explain='Để biết chiều cao trung bình của sinh viên cả trường, ta đo một mẫu và dùng x̄ làm “con số tốt nhất” cho μ. MLE là một cách có hệ thống để chọn con số đó.'))
