    notes += ex('1. Ví dụ 2.2: 400 cây con', '<p>8 lớp với điểm đại diện 7; 10.5; 12.5; 15; 18; 21; 24.5; 28 và tần số 18; 58; 62; 72; 57; 42; 36; 55. x̄ = 6920/400 = 17.3 cm; s² = 15 167.0/399 = 38.01 cm² (đã kiểm lại bằng chương trình).</p>')
